const rescheduleJob = `-- name: RescheduleJob :execrows
UPDATE jobs.jobs SET status = 'retry_scheduled', run_at = $1, locked_by = NULL, lock_expires_at = NULL, last_error = $2,
    attempt = attempt - $3::int
WHERE id = $4 AND locked_by = $5 AND status = 'running'
`

type RescheduleJobParams struct {
	RunAt         time.Time
	LastError     *string
	RefundAttempt int32
	ID            uuid.UUID
	WorkerID      *string
}

func (q *Queries) RescheduleJob(ctx context.Context, arg RescheduleJobParams) (int64, error) {
	result, err := q.db.Exec(ctx, rescheduleJob,
		arg.RunAt,
		arg.LastError,
		arg.RefundAttempt,
		arg.ID,
		arg.WorkerID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

