const upsertSchedule = `-- name: UpsertSchedule :exec
INSERT INTO jobs.job_schedules (tenant_id, key, cron, timezone, kind, payload, next_run_at, enabled)
VALUES (NULL, $1, $2, 'UTC', $3, '{}', now(), true)
ON CONFLICT (tenant_id, key) DO UPDATE SET cron = EXCLUDED.cron, kind = EXCLUDED.kind
`

type UpsertScheduleParams struct {
	Key  string
	Cron string
	Kind string
}

func (q *Queries) UpsertSchedule(ctx context.Context, arg UpsertScheduleParams) error {
	_, err := q.db.Exec(ctx, upsertSchedule, arg.Key, arg.Cron, arg.Kind)
	return err
}
